let pipeline = (1...).lazy
    .filter { $0.isMultiple(of: 2) }
    .map { $0 * $0 }
    .prefix(3)                      // lazy: nothing computed yet
for x in pipeline { print(x) }      // 4, 16, 36 - the consumer drives computation
let out = Array(pipeline)           // deliberate materialisation (recomputes)

