let nums = AsyncStream<Int> { cont in for i in 1...6 { cont.yield(i) }; cont.finish() }
let squares = nums
    .filter { $0.isMultiple(of: 2) }
    .map { $0 * $0 }               // AsyncFilterSequence / AsyncMapSequence, still lazy
for await s in squares { print(s) }     // 4, 16, 36 - consumption drives it
